const notes = new Map();
let counter = 0;

function generateId() {
  counter += 1;
  return 'n' + counter;
}

function textResult(text) {
  return { content: [{ type: 'text', text }] };
}

function asString(value) {
  return typeof value === 'string';
}

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a new note with a title and body, returning its generated id.',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', minLength: 1, description: 'Title of the note (required, non-empty).' },
          body: { type: 'string', minLength: 1, description: 'Body of the note (required, non-empty).' },
        },
        required: ['title', 'body'],
        additionalProperties: false,
      },
    },
    {
      name: 'note_get',
      description: 'Retrieve a previously created note by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string', minLength: 1, description: 'Id of the note to retrieve (required).' },
        },
        required: ['note_id'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  const params = args && typeof args === 'object' ? args : {};

  if (name === 'note_create') {
    const { title, body } = params;
    if (!asString(title) || title.length === 0) {
      throw new Error('Invalid arguments: "title" must be a non-empty string.');
    }
    if (!asString(body) || body.length === 0) {
      throw new Error('Invalid arguments: "body" must be a non-empty string.');
    }
    const id = generateId();
    notes.set(id, { id, title, body });
    return textResult(`Created note ${id} titled "${title}".`);
  }

  if (name === 'note_get') {
    const { note_id } = params;
    if (!asString(note_id) || note_id.length === 0) {
      throw new Error('Invalid arguments: "note_id" must be a non-empty string.');
    }
    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`Unknown note_id: ${note_id}`);
    }
    return textResult(`Title: ${note.title}\nBody: ${note.body}`);
  }

  throw new Error(`Unknown tool: ${name}`);
}

